import Foundation

struct TimetablePDFEntry: Decodable, Equatable, Sendable {
    let type: String?
    let tur: URL?
    let retur: URL?
}

/// Remote PDF timetables for STB, Prahova and other bus/tram lines (index bundled as
/// `timetable_pdfs.json`, generated by `build_timetable_pdfs.py`). PDFs are opened remotely,
/// not bundled. Suffix 0 is tur and suffix 1 is retur, verified against the app's line data.
struct TimetablePDFStore: Sendable {
    static let shared = TimetablePDFStore()

    private let entries: [String: TimetablePDFEntry]

    private init() {
        var decoded: [String: TimetablePDFEntry] = [:]
        if let url = LocalTransitDataManager.resolveResourceURL(name: "timetable_pdfs", ext: "json"),
           let data = try? Data(contentsOf: url) {
            do {
                decoded = try JSONDecoder().decode([String: TimetablePDFEntry].self, from: data)
            } catch {
                print("TimetablePDFStore: decode failed: \(error)")
            }
        }
        entries = decoded
    }

    /// Exact app line key (e.g. "100" or "PV1_403"). Returns nil when no PDF is indexed.
    func entry(forLine line: String) -> TimetablePDFEntry? {
        entries[line]
    }
}
